import 'package:flutter/material.dart';import 'dart:async';import 'dart:math';import 'package:flutter/services.dart';import 'quiz_questions.dart';import 'services/battle_websocket_service.dart';import 'quiz_api.dart';import 'audio_service.dart';import 'game_tutorial_overlay.dart';// ============================================================================// AVATAR HELPER// ============================================================================/// Returns the correct ImageProvider for both local asset paths and network URLs.ImageProvider _avatarProvider(String avatar) {  if (avatar.startsWith('http://') || avatar.startsWith('https://')) {    return NetworkImage(avatar);  }  return AssetImage(avatar);}// ============================================================================// DATA MODELS// ============================================================================class BattleRoom {  final String gameCode;  final String category;  final String difficulty;  BattleRoom({    required this.gameCode,    required this.category,    required this.difficulty,  });}// ============================================================================// MAIN BATTLE SCREEN (Room Creation/Join)// ============================================================================class WhizBattle extends StatefulWidget {  final String userAvatar;  final String userId;  final String username;  const WhizBattle({    super.key,    required this.userAvatar,    required this.userId,    required this.username,  });  @override  State<WhizBattle> createState() => _WhizBattleState();}class _WhizBattleState extends State<WhizBattle> {  // ── Page control ──  // 0 = Join/Create room, 1 = Difficulty & Category (host only)  int _currentPage = 0;  // ── Room / join state ──  final TextEditingController _roomCodeController = TextEditingController();  bool _isLoading = false;  // ── Host setup state (page 2) ──  String _selectedDifficulty = 'EASY';  String? _selectedMainCategory;  // ── Tutorial state ──  bool _showGameTutorial = false;  bool _checkingTutorialStatus = true;  // ── Difficulty options ──  final List<Map<String, String>> _difficultyLevels = [    {'value': 'EASY',      'display': 'Easy'},    {'value': 'AVERAGE',   'display': 'Average'},    {'value': 'DIFFICULT', 'display': 'Difficult'},  ];  // ── Topics per difficulty ──  final Map<String, List<String>> _mathTopics = {    'EASY': [      'Addition & Subtraction', 'Multiplication', 'Division',      'Counting & Numbers', 'Basic Shapes', 'Comparing Numbers',      'Number Patterns', 'Telling Time',    ],    'AVERAGE': [      'Fractions & Decimals', 'Algebra Basics', 'Geometry',      'Ratios & Proportions', 'Percentages', 'Area & Perimeter',      'Integers', 'Word Problems',    ],    'DIFFICULT': [      'Calculus', 'Statistics & Probability', 'Advanced Algebra',      'Trigonometry', 'Linear Equations', 'Polynomials',      'Logarithms', 'Matrices',    ],  };  final Map<String, List<String>> _scienceTopics = {    'EASY': [      'Plants & Animals', 'Human Body', 'Weather & Seasons',      'Day & Night', 'Rocks & Soil', 'Food Chains',      'Simple Machines', 'Senses',    ],    'AVERAGE': [      'Ecosystems', 'Cells & Organisms', 'Matter & States',      'Forces & Motion', 'Solar System', 'Energy Types',      'Water Cycle', 'Photosynthesis',    ],    'DIFFICULT': [      'Molecular Biology', 'Advanced Chemistry', 'Quantum Physics',      'Genetics & DNA', 'Thermodynamics', 'Electromagnetism',      'Chemical Reactions', 'Atomic Structure',    ],  };  // ── Helpers ──  String get _categoryForApi => _selectedMainCategory != null      ? (_selectedMainCategory![0] + _selectedMainCategory!.substring(1).toLowerCase())      : 'Science';  String get _difficultyForApi {    switch (_selectedDifficulty) {      case 'EASY':      return 'Easy';      case 'AVERAGE':   return 'Average';      case 'DIFFICULT': return 'Difficult';      default:          return 'Easy';    }  }  @override  void initState() {    super.initState();    AudioService().playBattleMusic();    WidgetsBinding.instance.addPostFrameCallback((_) {      _checkGameTutorialStatus();    });  }  @override  void dispose() {    _roomCodeController.dispose();    super.dispose();  }  String _generateRoomCode() {    const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';    return List.generate(6, (index) => chars[Random().nextInt(chars.length)]).join();  }  Future<void> _checkGameTutorialStatus() async {    try {      final shouldShow = await GameTutorialOverlay.shouldShowTutorial(        widget.userId, 'battle',      );      if (shouldShow && mounted) {        await Future.delayed(const Duration(milliseconds: 500));        if (mounted) {          setState(() {            _showGameTutorial = true;            _checkingTutorialStatus = false;          });        }      } else {        if (mounted) setState(() => _checkingTutorialStatus = false);      }    } catch (e) {      debugPrint('Error checking tutorial status: $e');      if (mounted) setState(() => _checkingTutorialStatus = false);    }  }  // ── Called after host picks difficulty + category ──  Future<void> _createRoom() async {    if (_isLoading) return;    try { await AudioService().playClickSound(); } catch (e) { debugPrint('$e'); }    setState(() => _isLoading = true);    final roomCode = _generateRoomCode();    final wsService = BattleWebSocketService();    final connected = await wsService.connect(widget.userId);    if (!connected) {      if (mounted) {        ScaffoldMessenger.of(context).showSnackBar(          const SnackBar(content: Text('❌ Failed to connect to server')),        );        setState(() => _isLoading = false);      }      return;    }    wsService.createRoom(      roomCode: roomCode,      hostName: widget.username,      hostAvatar: widget.userAvatar,      category: _categoryForApi,      difficulty: _difficultyForApi,    );    await Future.delayed(const Duration(milliseconds: 500));    if (mounted) {      setState(() => _isLoading = false);      Navigator.push(        context,        MaterialPageRoute(          builder: (context) => BattleGameScreen(            battleRoom: BattleRoom(              gameCode: roomCode,              category: _categoryForApi,              difficulty: _difficultyForApi,            ),            userId: widget.userId,            username: widget.username,            userAvatar: widget.userAvatar,            isHost: true,            webSocketService: wsService,          ),        ),      );    }  }  // ── Join an existing room ──  Future<void> _joinRoom() async {    final roomCode = _roomCodeController.text.trim().toUpperCase();    if (roomCode.isEmpty) {      ScaffoldMessenger.of(context).showSnackBar(        const SnackBar(content: Text('Please enter a room code')),      );      return;    }    try { await AudioService().playClickSound(); } catch (e) { debugPrint('$e'); }    setState(() => _isLoading = true);    final wsService = BattleWebSocketService();    final connected = await wsService.connect(widget.userId);    if (!connected) {      if (mounted) {        ScaffoldMessenger.of(context).showSnackBar(          const SnackBar(content: Text('Failed to connect to server')),        );        setState(() => _isLoading = false);      }      return;    }    String? hostName;    String? hostAvatar;    String? errorMessage;    final subscription = wsService.messages.listen((message) {      final event = message['event'];      if (event == 'join_success') {        hostName = message['host_name'];        hostAvatar = message['host_avatar'];      } else if (event == 'error') {        errorMessage = message['message'];      }    });    wsService.joinRoom(      roomCode: roomCode,      playerName: widget.username,      playerAvatar: widget.userAvatar,    );    for (int i = 0; i < 50; i++) {      await Future.delayed(const Duration(milliseconds: 100));      if (hostName != null || errorMessage != null) break;    }    subscription.cancel();    if (errorMessage != null) {      if (mounted) {        wsService.disconnect();        ScaffoldMessenger.of(context).showSnackBar(          SnackBar(content: Text('❌ $errorMessage'), backgroundColor: Colors.red),        );        setState(() => _isLoading = false);      }      return;    }    if (hostName == null) {      if (mounted) {        wsService.disconnect();        ScaffoldMessenger.of(context).showSnackBar(          const SnackBar(            content: Text('❌ Invalid code. Please check and try again.'),            backgroundColor: Colors.red,          ),        );        setState(() => _isLoading = false);      }      return;    }    if (mounted) {      setState(() => _isLoading = false);      Navigator.push(        context,        MaterialPageRoute(          builder: (context) => BattleGameScreen(            battleRoom: BattleRoom(              gameCode: roomCode,              category: _categoryForApi,              difficulty: _difficultyForApi,            ),            userId: widget.userId,            username: widget.username,            userAvatar: widget.userAvatar,            isHost: false,            webSocketService: wsService,            initialOpponentName: hostName,            initialOpponentAvatar: hostAvatar,          ),        ),      );    }  }  // ══════════════════════════════════════════════════════════════  //  BUILD  // ══════════════════════════════════════════════════════════════  @override  Widget build(BuildContext context) {    return Stack(      children: [        Scaffold(          backgroundColor: Colors.white,          body: _checkingTutorialStatus              ? const Center(            child: CircularProgressIndicator(color: Color(0xFFC571E2)),          )              : Column(            children: [              _buildTopBar(),              Expanded(                child: _currentPage == 0                    ? _buildJoinCreatePage()                    : _buildSetupPage(),              ),            ],          ),        ),        if (_showGameTutorial)          GameTutorialOverlay(            userId: widget.userId,            gameType: 'battle',            onComplete: () => setState(() => _showGameTutorial = false),          ),      ],    );  }  // ── Shared top bar ──  Widget _buildTopBar() {    return Column(      mainAxisSize: MainAxisSize.min,      children: [        Container(          color: Colors.white,          padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 4),          child: Row(            children: [              Image.asset(                'assets/images-logo/newhomepagelogo.png',                width: 150, height: 50, fit: BoxFit.contain,              ),              const Spacer(),              Container(                width: 44, height: 44,                decoration: BoxDecoration(                  shape: BoxShape.circle,                  border: Border.all(color: const Color(0xFFC571E2), width: 3),                ),                child: ClipOval(                  child: Image(image: _avatarProvider(widget.userAvatar), fit: BoxFit.cover),                ),              ),            ],          ),        ),        Container(          width: double.infinity,          padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 14),          decoration: const BoxDecoration(            color: Color(0xFFC571E2),            boxShadow: [BoxShadow(color: Colors.black12, blurRadius: 3, offset: Offset(0, 2))],          ),          child: Row(            children: [              IconButton(                icon: const Icon(Icons.arrow_back_ios, color: Colors.black87, size: 20),                onPressed: () async {                  try { await AudioService().playClickSound(); } catch (e) { debugPrint('$e'); }                  if (_currentPage == 1) {                    setState(() => _currentPage = 0);                  } else {                    Navigator.pop(context);                  }                },                padding: EdgeInsets.zero,                constraints: const BoxConstraints(),              ),              Expanded(                child: Text(                  _currentPage == 0 ? 'Whiz Battle' : 'Set Up Battle',                  textAlign: TextAlign.center,                  style: const TextStyle(                    color: Colors.black87,                    fontSize: 17,                    fontWeight: FontWeight.bold,                  ),                ),              ),              const SizedBox(width: 28),            ],          ),        ),      ],    );  }  // ══════════════════════════════════════════════════════════════  //  PAGE 1 — Join or Create  // ══════════════════════════════════════════════════════════════  Widget _buildJoinCreatePage() {    return Center(      child: SingleChildScrollView(        child: Padding(          padding: const EdgeInsets.symmetric(horizontal: 40, vertical: 36),          child: ConstrainedBox(            constraints: const BoxConstraints(maxWidth: 520),            child: Column(              crossAxisAlignment: CrossAxisAlignment.stretch,              children: [                // ── Create Room card ──                _buildActionCard(                  icon: Icons.add_circle_outline_rounded,                  title: 'Create a Room',                  subtitle: 'Host a new battle and invite a friend',                  buttonLabel: 'CREATE ROOM',                  onTap: () => setState(() => _currentPage = 1),                ),                const SizedBox(height: 20),                // ── OR divider ──                Row(children: [                  const Expanded(child: Divider(thickness: 1)),                  Padding(                    padding: const EdgeInsets.symmetric(horizontal: 16),                    child: Text(                      'OR',                      style: TextStyle(                        fontSize: 13, fontWeight: FontWeight.w800,                        color: Colors.grey[500], letterSpacing: 1,                      ),                    ),                  ),                  const Expanded(child: Divider(thickness: 1)),                ]),                const SizedBox(height: 20),                // ── Join Room card ──                Container(                  padding: const EdgeInsets.all(24),                  decoration: BoxDecoration(                    color: Colors.white,                    borderRadius: BorderRadius.circular(20),                    border: Border.all(color: Colors.black87, width: 2),                  ),                  child: Column(                    crossAxisAlignment: CrossAxisAlignment.start,                    children: [                      Row(children: [                        Container(                          width: 44, height: 44,                          decoration: BoxDecoration(                            color: Colors.grey[100],                            borderRadius: BorderRadius.circular(12),                          ),                          child: const Icon(Icons.login_rounded, size: 24, color: Colors.black87),                        ),                        const SizedBox(width: 14),                        Column(                          crossAxisAlignment: CrossAxisAlignment.start,                          children: [                            const Text(                              'Join a Room',                              style: TextStyle(fontSize: 16, fontWeight: FontWeight.w900, color: Colors.black87),                            ),                            Text(                              "Enter a code to join a friend's battle",                              style: TextStyle(fontSize: 12, color: Colors.grey[500], fontWeight: FontWeight.w600),                            ),                          ],                        ),                      ]),                      const SizedBox(height: 20),                      TextField(                        controller: _roomCodeController,                        decoration: InputDecoration(                          hintText: 'Room Code (e.g. AB12CD)',                          hintStyle: TextStyle(color: Colors.grey[400], letterSpacing: 2, fontWeight: FontWeight.w600),                          filled: true,                          fillColor: Colors.grey[50],                          contentPadding: const EdgeInsets.symmetric(horizontal: 20, vertical: 16),                          border: OutlineInputBorder(                            borderRadius: BorderRadius.circular(50),                            borderSide: BorderSide(color: Colors.grey[300]!, width: 1.5),                          ),                          enabledBorder: OutlineInputBorder(                            borderRadius: BorderRadius.circular(50),                            borderSide: BorderSide(color: Colors.grey[300]!, width: 1.5),                          ),                          focusedBorder: OutlineInputBorder(                            borderRadius: BorderRadius.circular(50),                            borderSide: const BorderSide(color: Color(0xFFC571E2), width: 2),                          ),                        ),                        textCapitalization: TextCapitalization.characters,                        maxLength: 6,                        textAlign: TextAlign.center,                        style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold, letterSpacing: 3),                        buildCounter: (_, {required currentLength, required isFocused, maxLength}) => null,                      ),                      const SizedBox(height: 14),                      SizedBox(                        width: double.infinity,                        child: MouseRegion(                          cursor: SystemMouseCursors.click,                          child: GestureDetector(                            onTap: _isLoading ? null : _joinRoom,                            child: AnimatedContainer(                              duration: const Duration(milliseconds: 200),                              padding: const EdgeInsets.symmetric(vertical: 16),                              decoration: BoxDecoration(                                color: Colors.white,                                borderRadius: BorderRadius.circular(50),                                border: Border.all(color: Colors.black87, width: 2),                              ),                              child: _isLoading                                  ? const Center(                                child: SizedBox(                                  width: 20, height: 20,                                  child: CircularProgressIndicator(strokeWidth: 2, color: Colors.black87),                                ),                              )                                  : const Text(                                'JOIN ROOM',                                textAlign: TextAlign.center,                                style: TextStyle(                                  fontSize: 14, fontWeight: FontWeight.w900,                                  letterSpacing: 1, color: Colors.black87,                                ),                              ),                            ),                          ),                        ),                      ),                    ],                  ),                ),              ],            ),          ),        ),      ),    );  }  Widget _buildActionCard({    required IconData icon,    required String title,    required String subtitle,    required String buttonLabel,    required VoidCallback onTap,  }) {    return Container(      padding: const EdgeInsets.all(24),      decoration: BoxDecoration(        color: const Color(0xFFC571E2),        borderRadius: BorderRadius.circular(20),        boxShadow: [          BoxShadow(            color: const Color(0xFFC571E2).withValues(alpha: 0.45),            blurRadius: 12, offset: const Offset(0, 5),          ),        ],      ),      child: Column(        crossAxisAlignment: CrossAxisAlignment.start,        children: [          Row(children: [            Container(              width: 44, height: 44,              decoration: BoxDecoration(                color: Colors.black.withValues(alpha: 0.1),                borderRadius: BorderRadius.circular(12),              ),              child: Icon(icon, size: 24, color: Colors.black87),            ),            const SizedBox(width: 14),            Column(              crossAxisAlignment: CrossAxisAlignment.start,              children: [                Text(title,                    style: const TextStyle(fontSize: 16, fontWeight: FontWeight.w900, color: Colors.black87)),                Text(subtitle,                    style: TextStyle(fontSize: 12, color: Colors.black.withValues(alpha: 0.5), fontWeight: FontWeight.w600)),              ],            ),          ]),          const SizedBox(height: 20),          SizedBox(            width: double.infinity,            child: MouseRegion(              cursor: SystemMouseCursors.click,              child: GestureDetector(                onTap: onTap,                child: Container(                  padding: const EdgeInsets.symmetric(vertical: 16),                  decoration: BoxDecoration(                    color: Colors.black87,                    borderRadius: BorderRadius.circular(50),                  ),                  child: Text(                    buttonLabel,                    textAlign: TextAlign.center,                    style: const TextStyle(                      fontSize: 14, fontWeight: FontWeight.w900,                      letterSpacing: 1, color: Colors.white,                    ),                  ),                ),              ),            ),          ),        ],      ),    );  }  // ══════════════════════════════════════════════════════════════  //  PAGE 2 — Difficulty & Category (host only)  // ══════════════════════════════════════════════════════════════  Widget _buildSetupPage() {    return Center(      child: SingleChildScrollView(        child: Padding(          padding: const EdgeInsets.symmetric(horizontal: 40, vertical: 30),          child: ConstrainedBox(            constraints: const BoxConstraints(maxWidth: 600),            child: Column(              crossAxisAlignment: CrossAxisAlignment.start,              children: [                const Text(                  'DIFFICULTY',                  style: TextStyle(fontSize: 11, fontWeight: FontWeight.w800, color: Colors.black54, letterSpacing: 1.2),                ),                const SizedBox(height: 10),                _buildDifficultyRow(),                const SizedBox(height: 28),                const Text(                  'CATEGORY',                  style: TextStyle(fontSize: 11, fontWeight: FontWeight.w800, color: Colors.black54, letterSpacing: 1.2),                ),                const SizedBox(height: 10),                _buildExpandableCategoryCard('Math', Icons.calculate),                const SizedBox(height: 14),                _buildExpandableCategoryCard('Science', Icons.science),                const SizedBox(height: 40),                Center(child: _buildCreateButton()),              ],            ),          ),        ),      ),    );  }  Widget _buildDifficultyRow() {    return Row(      children: _difficultyLevels.map((d) {        final isSelected = _selectedDifficulty == d['value'];        return Expanded(          child: Padding(            padding: const EdgeInsets.symmetric(horizontal: 6),            child: MouseRegion(              cursor: SystemMouseCursors.click,              child: GestureDetector(                onTap: () async {                  try { await AudioService().playClickSound(); } catch (e) { debugPrint('$e'); }                  setState(() {                    _selectedDifficulty = d['value']!;                    _selectedMainCategory = null;                  });                },                child: AnimatedContainer(                  duration: const Duration(milliseconds: 200),                  padding: const EdgeInsets.symmetric(vertical: 16),                  decoration: BoxDecoration(                    color: isSelected ? const Color(0xFFC571E2) : Colors.white,                    borderRadius: BorderRadius.circular(30),                    border: Border.all(                      color: isSelected ? const Color(0xFFC571E2) : Colors.black87,                      width: 2,                    ),                    boxShadow: isSelected                        ? [BoxShadow(                      color: const Color(0xFFC571E2).withValues(alpha: 0.5),                      blurRadius: 8, offset: const Offset(0, 3),                    )]                        : [],                  ),                  child: Text(                    d['display']!.toUpperCase(),                    textAlign: TextAlign.center,                    style: const TextStyle(                      fontSize: 14, fontWeight: FontWeight.bold,                      color: Colors.black87, letterSpacing: 0.5,                    ),                  ),                ),              ),            ),          ),        );      }).toList(),    );  }  Widget _buildExpandableCategoryCard(String category, IconData icon) {    final isExpanded = _selectedMainCategory?.toLowerCase() == category.toLowerCase();    final topics = category.toLowerCase() == 'math'        ? _mathTopics[_selectedDifficulty] ?? []        : _scienceTopics[_selectedDifficulty] ?? [];    return MouseRegion(      cursor: SystemMouseCursors.click,      child: GestureDetector(        onTap: () async {          try { await AudioService().playClickSound(); } catch (e) { debugPrint('$e'); }          setState(() {            _selectedMainCategory = isExpanded ? null : category.toUpperCase();          });        },        child: AnimatedContainer(          duration: const Duration(milliseconds: 200),          decoration: BoxDecoration(            color: Colors.white,            borderRadius: BorderRadius.circular(16),            border: Border.all(              color: isExpanded ? const Color(0xFFC571E2) : Colors.black87,              width: 2,            ),            boxShadow: isExpanded                ? [BoxShadow(              color: const Color(0xFFC571E2).withValues(alpha: 0.35),              blurRadius: 10, offset: const Offset(0, 4),            )]                : [],          ),          child: ClipRRect(            borderRadius: BorderRadius.circular(14),            child: Column(              children: [                // Yellow header                Container(                  width: double.infinity,                  padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 18),                  color: isExpanded ? const Color(0xFFC571E2) : Colors.white,                  child: Row(                    children: [                      Container(                        width: 38, height: 38,                        decoration: BoxDecoration(                          color: Colors.black.withValues(alpha: 0.08),                          borderRadius: BorderRadius.circular(10),                        ),                        child: Icon(icon, color: Colors.black87, size: 22),                      ),                      const SizedBox(width: 14),                      Text(                        category.toUpperCase(),                        style: const TextStyle(                          fontSize: 17, fontWeight: FontWeight.w900,                          color: Colors.black87, letterSpacing: 0.5,                        ),                      ),                      const Spacer(),                      Container(                        width: 28, height: 28,                        decoration: BoxDecoration(                          color: Colors.black.withValues(alpha: 0.1),                          shape: BoxShape.circle,                        ),                        child: Icon(                          isExpanded ? Icons.remove : Icons.add,                          color: Colors.black87, size: 18,                        ),                      ),                    ],                  ),                ),                // White topics body                AnimatedCrossFade(                  firstChild: const SizedBox(width: double.infinity, height: 0),                  secondChild: Container(                    width: double.infinity,                    padding: const EdgeInsets.fromLTRB(16, 14, 16, 18),                    color: Colors.white,                    child: Column(                      crossAxisAlignment: CrossAxisAlignment.start,                      children: [                        const Text(                          'TOPICS',                          style: TextStyle(                            fontSize: 10, fontWeight: FontWeight.w800,                            color: Colors.black45, letterSpacing: 1.3,                          ),                        ),                        const SizedBox(height: 10),                        Wrap(                          spacing: 8, runSpacing: 8,                          children: topics.map((topic) => Container(                            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 8),                            decoration: BoxDecoration(                              color: Colors.grey[100],                              borderRadius: BorderRadius.circular(50),                              border: Border.all(color: Colors.grey[300]!, width: 1.5),                            ),                            child: Text(                              topic,                              style: const TextStyle(                                fontSize: 13, fontWeight: FontWeight.w600, color: Colors.black87,                              ),                            ),                          )).toList(),                        ),                      ],                    ),                  ),                  crossFadeState: isExpanded                      ? CrossFadeState.showSecond                      : CrossFadeState.showFirst,                  duration: const Duration(milliseconds: 250),                ),              ],            ),          ),        ),      ),    );  }  Widget _buildCreateButton() {    final isEnabled = _selectedMainCategory != null && !_isLoading;    return MouseRegion(      cursor: isEnabled ? SystemMouseCursors.click : SystemMouseCursors.forbidden,      child: GestureDetector(        onTap: isEnabled ? _createRoom : null,        child: AnimatedContainer(          duration: const Duration(milliseconds: 200),          padding: const EdgeInsets.symmetric(horizontal: 60, vertical: 16),          decoration: BoxDecoration(            color: isEnabled ? const Color(0xFFC571E2) : Colors.grey[300],            borderRadius: BorderRadius.circular(30),            boxShadow: isEnabled                ? [BoxShadow(              color: const Color(0xFFC571E2).withValues(alpha: 0.5),              blurRadius: 12, offset: const Offset(0, 4),            )]                : [],          ),          child: _isLoading              ? const SizedBox(            width: 22, height: 22,            child: CircularProgressIndicator(strokeWidth: 2.5, color: Colors.black87),          )              : Text(            'CREATE ROOM',            style: TextStyle(              fontSize: 15, fontWeight: FontWeight.w900,              letterSpacing: 1, color: isEnabled ? Colors.black87 : Colors.grey[600],            ),          ),        ),      ),    );  }}// ============================================================================// BATTLE GAME SCREEN// ============================================================================class BattleGameScreen extends StatefulWidget {  final BattleRoom battleRoom;  final String userId;  final String username;  final String userAvatar;  final bool isHost;  final BattleWebSocketService webSocketService;  final String? initialOpponentName;  final String? initialOpponentAvatar;  const BattleGameScreen({    super.key,    required this.battleRoom,    required this.userId,    required this.username,    required this.userAvatar,    required this.isHost,    required this.webSocketService,    this.initialOpponentName,    this.initialOpponentAvatar,  });  @override  State<BattleGameScreen> createState() => _BattleGameScreenState();}class _BattleGameScreenState extends State<BattleGameScreen> {  String get baseUrl => "http://localhost/api";  List<Question> questions = [];  int currentQuestionIndex = 0;  int myScore = 0;  int opponentScore = 0;  bool gameStarted = false;  int correctAnswersCount = 0;  Map<String, dynamic>? badgeAwarded;  String opponentName = "Waiting...";  String opponentAvatar = "assets/images-avatars/default.png";  bool opponentJoined = false;  Timer? questionTimer;  int timeRemaining = 15;  bool showFeedback = false;  bool wasCorrect = false;  int earnedPoints = 0;  bool waitingForOpponent = false;  String? _selectedAnswer;  late StreamSubscription wsSubscription;  @override  void initState() {    super.initState();    if (widget.initialOpponentName != null) {      opponentName = widget.initialOpponentName!;      opponentAvatar = widget.initialOpponentAvatar ?? "assets/images-avatars/default.png";      opponentJoined = true;      debugPrint('🎯 Initialized with opponent: $opponentName');    }    _listenToWebSocket();  }  @override  void dispose() {    questionTimer?.cancel();    wsSubscription.cancel();    super.dispose();  }  void _listenToWebSocket() {    debugPrint('🎧 Starting to listen to WebSocket messages...');    wsSubscription = widget.webSocketService.messages.listen((message) {      if (!mounted) {        debugPrint('⚠️ Received message but widget not mounted');        return;      }      final event = message['event'];      debugPrint('┌─────────────────────────────────────────');      debugPrint('📨 Event received: $event');      debugPrint('📨 Full message: $message');      debugPrint('📨 isHost: ${widget.isHost}');      debugPrint('📨 Current opponentName: $opponentName');      debugPrint('📨 Current opponentJoined: $opponentJoined');      debugPrint('└─────────────────────────────────────────');      switch (event) {        case 'room_created':          debugPrint('✅ Room created successfully');          break;        case 'opponent_joined':          debugPrint('👥 *** OPPONENT_JOINED EVENT PROCESSING ***');          debugPrint('   Received opponent_name: ${message['opponent_name']}');          debugPrint('   Received opponent_avatar: ${message['opponent_avatar']}');          if (mounted) {            setState(() {              opponentName = message['opponent_name'] ?? 'Opponent';              opponentAvatar = message['opponent_avatar'] ?? 'assets/images-avatars/default.png';              opponentJoined = true;            });            debugPrint('✅ State updated!');            debugPrint('   NEW opponentName: $opponentName');            debugPrint('   NEW opponentAvatar: $opponentAvatar');            debugPrint('   NEW opponentJoined: $opponentJoined');          } else {            debugPrint('⚠️ Widget not mounted, cannot update state');          }          break;        case 'join_success':          debugPrint('✅ Join success event received');          debugPrint('   Host Name: ${message['host_name']}');          debugPrint('   Host Avatar: ${message['host_avatar']}');          if (mounted) {            setState(() {              opponentName = message['host_name'] ?? 'Host';              opponentAvatar = message['host_avatar'] ?? 'assets/images-avatars/default.png';              opponentJoined = true;            });            debugPrint('✅ State updated for joiner - opponentName: $opponentName');          }          break;        case 'game_started':          debugPrint('🎮 game_started event received');          debugPrint('   Current opponentName before game start: $opponentName');          debugPrint('   Current opponentJoined before game start: $opponentJoined');          _handleGameStarted(message);          break;        case 'score_update':          _handleScoreUpdate(message);          break;        case 'both_answered':          _handleBothAnswered(message);          break;        case 'next_question':          _nextQuestion();          break;        case 'game_over':          _handleGameOver(message);          break;        case 'player_left':        case 'player_disconnected':          debugPrint('❌ Opponent left or disconnected');          final wonByForfeit = message['won_by_forfeit'] ?? false;          if (wonByForfeit) {            _showOpponentLeftDialog();          } else {            _showOpponentLeftDialog();          }          break;        case 'error':          ScaffoldMessenger.of(context).showSnackBar(            SnackBar(content: Text(message['message'] ?? 'Error occurred')),          );          break;      }    });  }  void _handleGameStarted(Map<String, dynamic> message) {    final questionsData = message['questions'] as List<dynamic>?;    if (questionsData == null) {      debugPrint('❌ No questions received');      return;    }    debugPrint('🎮 Game starting...');    debugPrint('   My name: ${widget.username}');    debugPrint('   Opponent name: $opponentName');    debugPrint('   Opponent joined: $opponentJoined');    questions = questionsData.map((q) {      final qMap = q as Map<String, dynamic>;      return Question(        question: qMap['question'] ?? '',        questionImage: qMap['question_image'],        options: [          qMap['choice_a'] ?? '',          qMap['choice_b'] ?? '',          qMap['choice_c'] ?? '',          qMap['choice_d'] ?? '',        ],        optionImages: [          qMap['choice_a_image'],          qMap['choice_b_image'],          qMap['choice_c_image'],          qMap['choice_d_image'],        ],        correctAnswer: qMap['correct_answer'] ?? '',      );    }).toList();    setState(() {      gameStarted = true;      currentQuestionIndex = 0;      correctAnswersCount = 0;    });    _startQuestionTimer();    debugPrint('🎮 Game started with ${questions.length} questions');  }  void _handleScoreUpdate(Map<String, dynamic> message) {    // Score updates are handled in both_answered  }  void _handleBothAnswered(Map<String, dynamic> message) {    final scores = message['scores'] as Map<String, dynamic>?;    if (scores != null) {      setState(() {        myScore = (scores[widget.userId] as num?)?.toInt() ?? myScore;        scores.forEach((key, value) {          if (key != widget.userId) {            opponentScore = (value as num?)?.toInt() ?? opponentScore;          }        });        waitingForOpponent = false;      });    }  }  void _handleGameOver(Map<String, dynamic> message) async {    final winnerId = message['winner_id'] as String?;    final didIWin = winnerId == widget.userId;    try {      final response = await QuizApiService.saveBattleResult(        playerId: widget.userId,        category: widget.battleRoom.category,        difficulty: widget.battleRoom.difficulty,        score: myScore,        result: didIWin ? 'won' : 'lost',        questionsAnswered: questions.length,        correctAnswers: correctAnswersCount,        battleId: widget.battleRoom.gameCode,      );      if (response != null && response['badge_awarded'] != null) {        badgeAwarded = response['badge_awarded'];        debugPrint('🎯 Badge info received: $badgeAwarded');      }    } catch (e) {      debugPrint('Error saving: $e');    }    if (!mounted) return;    Navigator.of(context).pushReplacement(      MaterialPageRoute(        builder: (context) => BattleResultScreen(          category: widget.battleRoom.category,          difficulty: widget.battleRoom.difficulty,          gameCode: widget.battleRoom.gameCode,          myScore: myScore,          opponentScore: opponentScore,          myName: widget.username,          opponentName: opponentName,          myAvatar: widget.userAvatar,          opponentAvatar: opponentAvatar,          totalQuestions: questions.length,          didIWin: didIWin,          badgeAwarded: badgeAwarded,        ),      ),    );  }  void _startQuestionTimer() {    timeRemaining = 15;    questionTimer?.cancel();    questionTimer = Timer.periodic(const Duration(seconds: 1), (timer) {      if (!mounted) {        timer.cancel();        return;      }      setState(() {        if (timeRemaining > 0) {          timeRemaining--;        } else {          timer.cancel();          if (!showFeedback) {            _handleAnswer('');          }        }      });    });  }  void _handleAnswer(String answer) {    if (showFeedback) return;    questionTimer?.cancel();    final isCorrect = answer == questions[currentQuestionIndex].correctAnswer;    final points = isCorrect ? timeRemaining : 0;    setState(() {      showFeedback = true;      wasCorrect = isCorrect;      earnedPoints = points;      myScore += points;      waitingForOpponent = true;      _selectedAnswer = answer;      if (isCorrect) {        correctAnswersCount++;      }    });    widget.webSocketService.submitAnswer(      roomCode: widget.battleRoom.gameCode,      isCorrect: isCorrect,      points: points,      questionIndex: currentQuestionIndex,    );    debugPrint('📝 Answer: ${isCorrect ? "✅" : "❌"} (+$points pts)');    debugPrint('📊 Correct answers so far: $correctAnswersCount/${currentQuestionIndex + 1}');  }  void _nextQuestion() {    setState(() {      currentQuestionIndex++;      showFeedback = false;      wasCorrect = false;      earnedPoints = 0;      waitingForOpponent = false;      _selectedAnswer = null;    });    _startQuestionTimer();  }  void _showOpponentLeftDialog() {    questionTimer?.cancel();    if (!mounted) return;    final didIWinByForfeit = gameStarted;    showDialog(      context: context,      barrierDismissible: false,      builder: (context) => AlertDialog(        title: Row(          children: [            Icon(              didIWinByForfeit ? Icons.emoji_events : Icons.warning_amber_rounded,              color: didIWinByForfeit ? Colors.amber : Colors.orange,              size: 32,            ),            const SizedBox(width: 12),            Text(didIWinByForfeit ? 'Victory!' : 'Battle Ended'),          ],        ),        content: Column(          mainAxisSize: MainAxisSize.min,          children: [            Text(              didIWinByForfeit                  ? 'Your opponent has left. You win by forfeit!'                  : 'Your opponent has left the battle.',              style: const TextStyle(fontSize: 16),            ),            const SizedBox(height: 16),            if (!didIWinByForfeit)              const Text(                'The room has been closed.',                style: TextStyle(fontSize: 14, color: Colors.grey),              ),          ],        ),        actions: [          ElevatedButton(            onPressed: () async {              try {                await AudioService().playClickSound();              } catch (e) {                debugPrint('Click sound not found: $e');              }              widget.webSocketService.disconnect();              AudioService().playHomepageMusic(); // ✅ Restore music              Navigator.of(context).pop();              Navigator.of(context).pop();            },            style: ElevatedButton.styleFrom(              backgroundColor: const Color(0xFFC571E2),              padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),            ),            child: const Text('OK', style: TextStyle(color: Colors.white)),          ),        ],      ),    );  }  Color _getDifficultyColor() {    switch (widget.battleRoom.difficulty.toUpperCase()) {      case "EASY":        return const Color(0xFF1D9358);      case "AVERAGE":        return const Color(0xFF046EB8);      case "DIFFICULT":        return const Color(0xFFBD442E);      default:        return const Color(0xFF1D9358);    }  }  String _getDifficultyBackground() {    switch (widget.battleRoom.difficulty.toUpperCase()) {      case "EASY":        return 'assets/images-bg/easy_bg.png';      case "AVERAGE":        return 'assets/images-bg/average_bg.png';      case "DIFFICULT":        return 'assets/images-bg/difficult_bg.png';      default:        return 'assets/images-bg/easy_bg.png';    }  }  @override  Widget build(BuildContext context) {    final color = _getDifficultyColor();    if (widget.isHost && !opponentJoined) {      return PopScope(        canPop: true,        onPopInvokedWithResult: (didPop, result) {          if (didPop) {            widget.webSocketService.leaveRoom(widget.battleRoom.gameCode);            widget.webSocketService.disconnect();            AudioService().playHomepageMusic(); // ✅ Restore music on back swipe          }        },        child: Scaffold(          backgroundColor: Colors.white,          body: Center(            child: Column(              mainAxisAlignment: MainAxisAlignment.center,              children: [                const CircularProgressIndicator(),                const SizedBox(height: 20),                const Text('Waiting for opponent...', style: TextStyle(fontSize: 18, fontFamily: 'Poppins')),                const SizedBox(height: 20),                // In WhizBattle.dart, around line 470 in the waiting room UI                Container(                  padding: const EdgeInsets.all(20),                  decoration: BoxDecoration(                    color: color,                    borderRadius: BorderRadius.circular(12),                  ),                  child: Column(                    children: [                      const Text('Room Code:', style: TextStyle(color: Colors.white)),                      const SizedBox(height: 8),                      Row(                        mainAxisSize: MainAxisSize.min,                        children: [                          Text(                            widget.battleRoom.gameCode,                            style: const TextStyle(                              fontSize: 32,                              fontWeight: FontWeight.bold,                              color: Colors.white,                              letterSpacing: 4,                            ),                          ),                          const SizedBox(width: 12),                          // ✅ ADD THIS COPY BUTTON                          IconButton(                            onPressed: () {                              Clipboard.setData(                                ClipboardData(text: widget.battleRoom.gameCode),                              );                              ScaffoldMessenger.of(context).showSnackBar(                                const SnackBar(                                  content: Text('Room code copied!'),                                  duration: Duration(seconds: 2),                                ),                              );                            },                            icon: const Icon(Icons.copy, color: Colors.white),                            tooltip: 'Copy Code',                          ),                        ],                      ),                    ],                  ),                ),                const SizedBox(height: 30),                OutlinedButton.icon(                  onPressed: () async {                    try {                      await AudioService().playClickSound();                    } catch (e) {                      debugPrint('Click sound not found: $e');                    }                    widget.webSocketService.leaveRoom(widget.battleRoom.gameCode);                    widget.webSocketService.disconnect();                    AudioService().playHomepageMusic(); // ✅ Restore music                    Navigator.of(context).pop();                  },                  icon: const Icon(Icons.close),                  label: const Text('Cancel'),                  style: OutlinedButton.styleFrom(                    foregroundColor: Colors.red,                    side: const BorderSide(color: Colors.red),                    padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),                  ),                ),              ],            ),          ),        ),      );    }    // HOST: Opponent joined, show START button    if (widget.isHost && opponentJoined && !gameStarted) {      return PopScope(        canPop: true,        onPopInvokedWithResult: (didPop, result) {          if (didPop) {            widget.webSocketService.leaveRoom(widget.battleRoom.gameCode);            widget.webSocketService.disconnect();            AudioService().playHomepageMusic(); // ✅ Restore music on back swipe          }        },        child: Scaffold(          backgroundColor: Colors.white,          body: Center(            child: Column(              mainAxisAlignment: MainAxisAlignment.center,              children: [                const Icon(Icons.check_circle, color: Color(0xFF1D9358), size: 80),                const SizedBox(height: 20),                const Text('Opponent Ready!', style: TextStyle(fontSize: 28, fontWeight: FontWeight.bold, fontFamily: 'Poppins')),                const SizedBox(height: 20),                Text(opponentName, style: const TextStyle(fontSize: 20, fontFamily: 'Poppins')),                const SizedBox(height: 40),                ElevatedButton(                  onPressed: () async {                    try {                      await AudioService().playClickSound();                    } catch (e) {                      debugPrint('Click sound not found: $e');                    }                    widget.webSocketService.startGame(widget.battleRoom.gameCode);                  },                  style: ElevatedButton.styleFrom(                    backgroundColor: color,                    padding: const EdgeInsets.symmetric(horizontal: 60, vertical: 20),                    shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(30)),                  ),                  child: const Text(                    'START BATTLE',                    style: TextStyle(fontSize: 22, fontWeight: FontWeight.bold, fontFamily: 'Poppins', color: Colors.white),                  ),                ),              ],            ),          ),        ),      );    }    // JOINER: Waiting for host to start    if (!widget.isHost && !gameStarted) {      return PopScope(        canPop: true,        onPopInvokedWithResult: (didPop, result) {          if (didPop) {            widget.webSocketService.leaveRoom(widget.battleRoom.gameCode);            widget.webSocketService.disconnect();            AudioService().playHomepageMusic(); // ✅ Restore music on back swipe          }        },        child: Scaffold(          backgroundColor: Colors.white,          body: Center(            child: Column(              mainAxisAlignment: MainAxisAlignment.center,              children: [                const CircularProgressIndicator(),                const SizedBox(height: 20),                const Text('Waiting for host to start...', style: TextStyle(fontSize: 18, fontFamily: 'Poppins')),                if (opponentJoined) ...[                  const SizedBox(height: 20),                  Text('Host: $opponentName', style: const TextStyle(fontSize: 16, fontFamily: 'Poppins')),                ],                const SizedBox(height: 30),                OutlinedButton.icon(                  onPressed: () async {                    try {                      await AudioService().playClickSound();                    } catch (e) {                      debugPrint('Click sound not found: $e');                    }                    widget.webSocketService.leaveRoom(widget.battleRoom.gameCode);                    widget.webSocketService.disconnect();                    AudioService().playHomepageMusic(); // ✅ Restore music                    Navigator.of(context).pop();                  },                  icon: const Icon(Icons.close),                  label: const Text('Leave'),                  style: OutlinedButton.styleFrom(                    foregroundColor: Colors.red,                    side: const BorderSide(color: Colors.red),                    padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),                  ),                ),              ],            ),          ),        ),      );    }    // GAME STARTED    if (gameStarted && questions.isNotEmpty) {      final question = questions[currentQuestionIndex];      return PopScope(        canPop: false,        onPopInvokedWithResult: (didPop, result) async {          if (!didPop) {            final shouldLeave = await showDialog<bool>(              context: context,              builder: (ctx) => AlertDialog(                title: const Text('Leave Battle?'),                content: const Text('Are you sure you want to leave? This will end the battle.'),                actions: [                  TextButton(                    onPressed: () => Navigator.of(ctx).pop(false),                    child: const Text('Cancel'),                  ),                  ElevatedButton(                    onPressed: () => Navigator.of(ctx).pop(true),                    style: ElevatedButton.styleFrom(backgroundColor: Colors.red),                    child: const Text('Leave', style: TextStyle(color: Colors.white)),                  ),                ],              ),            );            if (shouldLeave == true && context.mounted) {              widget.webSocketService.leaveRoom(widget.battleRoom.gameCode);              widget.webSocketService.disconnect();              AudioService().playHomepageMusic();              Navigator.of(context).popUntil((route) => route.isFirst);            }          }        },        child: Scaffold(          backgroundColor: Colors.white,          body: Container(            decoration: BoxDecoration(              image: DecorationImage(                image: AssetImage(_getDifficultyBackground()),                fit: BoxFit.cover,                opacity: 0.3,              ),            ),            child: Column(              children: [                // Header — matches quiz_game style                Container(                  width: double.infinity,                  color: color,                  padding: const EdgeInsets.symmetric(vertical: 10),                  child: Column(                    children: [                      Text(                        widget.battleRoom.category.toUpperCase(),                        style: const TextStyle(                          fontSize: 22,                          fontWeight: FontWeight.bold,                          color: Colors.white,                          letterSpacing: 1.2,                          fontFamily: 'Poppins',                        ),                      ),                      const SizedBox(height: 2),                      Text(                        widget.battleRoom.difficulty.toUpperCase(),                        style: const TextStyle(                          fontSize: 14,                          fontWeight: FontWeight.w500,                          color: Colors.white,                          fontFamily: 'Poppins',                        ),                      ),                    ],                  ),                ),                Expanded(                  child: showFeedback ? _buildFeedback() : _buildQuestion(question),                ),              ],            ),          ),        ),      );    }    // Loading    return const Scaffold(      backgroundColor: Color(0xFF87CEEB),      body: Center(child: CircularProgressIndicator()),    );  }  Widget _buildQuestion(Question question) {    final color = _getDifficultyColor();    final hasImageChoices = question.optionImages.any((img) => img != null && img.isNotEmpty);    return Center(      child: Container(        constraints: const BoxConstraints(maxWidth: 900),        margin: const EdgeInsets.symmetric(horizontal: 15, vertical: 10),        child: SingleChildScrollView(          child: Column(            mainAxisSize: MainAxisSize.min,            children: [              const SizedBox(height: 8),              // ── Player scoreboard ──              Row(                children: [                  Expanded(child: _buildPlayerCard(widget.username, widget.userAvatar, myScore, color)),                  Padding(                    padding: const EdgeInsets.symmetric(horizontal: 12),                    child: Text(                      'VS',                      style: TextStyle(                        fontSize: 28,                        fontWeight: FontWeight.w900,                        color: color,                        fontFamily: 'Poppins',                      ),                    ),                  ),                  Expanded(child: _buildPlayerCard(opponentName, opponentAvatar, opponentScore, color)),                ],              ),              const SizedBox(height: 12),              // ── Circular timer (matches quiz_game) ──              TweenAnimationBuilder<double>(                duration: const Duration(milliseconds: 300),                tween: Tween<double>(begin: timeRemaining / 15, end: timeRemaining / 15),                builder: (context, value, child) {                  return SizedBox(                    width: 90,                    height: 90,                    child: Stack(                      alignment: Alignment.center,                      children: [                        Container(                          width: 90,                          height: 90,                          decoration: BoxDecoration(                            shape: BoxShape.circle,                            color: Colors.white,                            boxShadow: [                              BoxShadow(                                color: Colors.black.withValues(alpha: 0.15),                                blurRadius: 10,                                offset: const Offset(0, 4),                              ),                            ],                          ),                        ),                        SizedBox(                          width: 90,                          height: 90,                          child: CircularProgressIndicator(                            value: timeRemaining / 15,                            strokeWidth: 6,                            backgroundColor: const Color(0xFFE0E0E0),                            valueColor: AlwaysStoppedAnimation<Color>(                              timeRemaining <= 5 ? Colors.red : color,                            ),                            strokeCap: StrokeCap.round,                          ),                        ),                        Text(                          '$timeRemaining',                          style: TextStyle(                            fontSize: 36,                            fontWeight: FontWeight.bold,                            color: timeRemaining <= 5 ? Colors.red : color,                            fontFamily: 'Poppins',                          ),                        ),                      ],                    ),                  );                },              ),              const SizedBox(height: 12),              // ── Question counter + score ──              Row(                mainAxisAlignment: MainAxisAlignment.spaceBetween,                children: [                  Text(                    'Question: ${currentQuestionIndex + 1} of ${questions.length}',                    style: const TextStyle(                      fontSize: 18, fontWeight: FontWeight.w600, fontFamily: 'Poppins',                    ),                  ),                  Text(                    'Score: $myScore',                    style: const TextStyle(                      fontSize: 18, fontWeight: FontWeight.w600, fontFamily: 'Poppins',                    ),                  ),                ],              ),              const SizedBox(height: 12),              // ── Question box (matches quiz_game) ──              Container(                width: double.infinity,                padding: const EdgeInsets.all(16),                decoration: BoxDecoration(                  color: Colors.white,                  borderRadius: BorderRadius.circular(12),                  border: Border.all(color: color, width: 2),                ),                child: Text(                  question.question,                  style: const TextStyle(                    fontSize: 18, fontWeight: FontWeight.w500, fontFamily: 'Poppins',                  ),                  textAlign: TextAlign.center,                ),              ),              const SizedBox(height: 12),              // ── Answer grid — image mode (4 across) or text mode (2x2) ──              if (hasImageChoices)                GridView.builder(                  shrinkWrap: true,                  physics: const NeverScrollableScrollPhysics(),                  gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(                    crossAxisCount: 4,                    mainAxisSpacing: 10,                    crossAxisSpacing: 12,                    childAspectRatio: 0.75,                  ),                  itemCount: question.options.length,                  itemBuilder: (context, index) => _buildAnswerButton(                    question.options[index],                    index,                    imageUrl: question.optionImages.length > index                        ? question.optionImages[index]                        : null,                  ),                )              else                GridView.builder(                  shrinkWrap: true,                  physics: const NeverScrollableScrollPhysics(),                  gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(                    crossAxisCount: 2,                    mainAxisSpacing: 10,                    crossAxisSpacing: 12,                    childAspectRatio: 3.5,                  ),                  itemCount: question.options.length,                  itemBuilder: (context, index) => _buildAnswerButton(                    question.options[index],                    index,                    imageUrl: null,                  ),                ),            ],          ),        ),      ),    );  }  static const List<Color> _answerColors = [    Color(0xFF1D9358), // green    Color(0xFFF39C12), // orange    Color(0xFF046EB8), // blue    Color(0xFFBD442E), // red  ];  Widget _buildAnswerButton(String answer, int index, {String? imageUrl}) {    final buttonColor = _answerColors[index % _answerColors.length];    final isSelected = _selectedAnswer == answer && showFeedback;    final hasImage = imageUrl != null && imageUrl.isNotEmpty;    return MouseRegion(      cursor: SystemMouseCursors.click,      child: GestureDetector(        onTap: () => _handleAnswer(answer),        child: AnimatedContainer(          duration: const Duration(milliseconds: 200),          decoration: BoxDecoration(            color: isSelected ? buttonColor : Colors.white,            borderRadius: BorderRadius.circular(8),            border: Border.all(color: buttonColor, width: isSelected ? 3 : 2),            boxShadow: [              BoxShadow(                color: Colors.black.withValues(alpha: 0.08),                blurRadius: 4,                offset: const Offset(0, 2),              ),            ],          ),          child: hasImage              ? Stack(            fit: StackFit.expand,            children: [              ClipRRect(                borderRadius: BorderRadius.circular(6),                child: Padding(                  padding: const EdgeInsets.all(8),                  child: Image.network(                    imageUrl,                    fit: BoxFit.contain,                    errorBuilder: (_, __, ___) => Center(                      child: Icon(Icons.broken_image_outlined,                          color: isSelected ? Colors.white : buttonColor, size: 32),                    ),                  ),                ),              ),              if (answer.isNotEmpty)                Positioned(                  bottom: 0, left: 0, right: 0,                  child: Container(                    padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 5),                    decoration: BoxDecoration(                      color: isSelected                          ? buttonColor.withValues(alpha: 0.9)                          : Colors.black.withValues(alpha: 0.5),                      borderRadius: const BorderRadius.vertical(bottom: Radius.circular(6)),                    ),                    child: Text(                      answer,                      style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600,                          color: Colors.white, fontFamily: 'Poppins'),                      textAlign: TextAlign.center,                      maxLines: 1,                      overflow: TextOverflow.ellipsis,                    ),                  ),                ),            ],          )              : Center(            child: Padding(              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),              child: Text(                answer,                style: TextStyle(                  fontSize: 18,                  fontWeight: FontWeight.w600,                  color: isSelected ? Colors.white : Colors.black87,                  fontFamily: 'Poppins',                  height: 1.2,                ),                textAlign: TextAlign.center,              ),            ),          ),        ),      ),    );  }  Widget _buildFeedback() {    final color = _getDifficultyColor();    return Center(      child: SingleChildScrollView(        child: Container(          constraints: const BoxConstraints(maxWidth: 700),          margin: const EdgeInsets.symmetric(horizontal: 25, vertical: 15),          child: Column(            mainAxisAlignment: MainAxisAlignment.center,            children: [              // ── Player scoreboard ──              Row(                children: [                  Expanded(child: _buildPlayerCard(widget.username, widget.userAvatar, myScore, color)),                  Padding(                    padding: const EdgeInsets.symmetric(horizontal: 12),                    child: Text(                      'VS',                      style: TextStyle(                        fontSize: 28, fontWeight: FontWeight.w900,                        color: color, fontFamily: 'Poppins',                      ),                    ),                  ),                  Expanded(child: _buildPlayerCard(opponentName, opponentAvatar, opponentScore, color)),                ],              ),              const SizedBox(height: 25),              // ── CORRECT / WRONG ──              Text(                wasCorrect ? 'CORRECT ANSWER!' : 'WRONG ANSWER!',                style: TextStyle(                  fontSize: 38,                  fontWeight: FontWeight.bold,                  color: wasCorrect ? const Color(0xFF1D9358) : const Color(0xFFE74C3C),                  fontFamily: 'Poppins',                  letterSpacing: 0.5,                ),                textAlign: TextAlign.center,              ),              const SizedBox(height: 25),              // ── Correct answer explanation box ──              Container(                width: double.infinity,                padding: const EdgeInsets.all(16),                decoration: BoxDecoration(                  color: Colors.white,                  borderRadius: BorderRadius.circular(12),                  border: Border.all(color: color, width: 2),                ),                child: Row(                  crossAxisAlignment: CrossAxisAlignment.start,                  children: [                    Padding(                      padding: const EdgeInsets.only(right: 12),                      child: Image.asset(                        'assets/images-icons/lightbulb.png',                        width: 35, height: 35,                        errorBuilder: (_, __, ___) =>                        const Icon(Icons.lightbulb, color: Color(0xFFFFC107), size: 40),                      ),                    ),                    Expanded(                      child: Column(                        crossAxisAlignment: CrossAxisAlignment.start,                        children: [                          Text(                            questions[currentQuestionIndex].question,                            style: const TextStyle(                              fontSize: 16, fontWeight: FontWeight.w600, fontFamily: 'Poppins',                            ),                          ),                          const SizedBox(height: 6),                          RichText(                            text: TextSpan(                              style: const TextStyle(                                fontSize: 14, fontFamily: 'Poppins', color: Colors.black87,                              ),                              children: [                                const TextSpan(                                  text: 'Answer: ',                                  style: TextStyle(fontWeight: FontWeight.w600),                                ),                                TextSpan(                                  text: questions[currentQuestionIndex].correctAnswer,                                  style: const TextStyle(fontWeight: FontWeight.bold),                                ),                              ],                            ),                          ),                          if (wasCorrect) ...[                            const SizedBox(height: 6),                            Text(                              '+$earnedPoints pts',                              style: const TextStyle(                                fontSize: 14, fontWeight: FontWeight.bold,                                color: Color(0xFF1D9358), fontFamily: 'Poppins',                              ),                            ),                          ],                        ],                      ),                    ),                  ],                ),              ),              // ── Waiting for opponent ──              if (waitingForOpponent) ...[                const SizedBox(height: 25),                const CircularProgressIndicator(),                const SizedBox(height: 10),                const Text(                  'Waiting for opponent...',                  style: TextStyle(fontSize: 16, color: Colors.grey, fontFamily: 'Poppins'),                ),              ],            ],          ),        ),      ),    );  }  Widget _buildPlayerCard(String name, String avatar, int score, Color color) {    return Container(      padding: const EdgeInsets.symmetric(horizontal: 10, vertical: 10),      decoration: BoxDecoration(        color: Colors.white,        borderRadius: BorderRadius.circular(14),        border: Border.all(color: color, width: 2.5),        boxShadow: [          BoxShadow(            color: Colors.black.withValues(alpha: 0.10),            blurRadius: 8,            offset: const Offset(0, 3),          ),        ],      ),      child: Row(        children: [          CircleAvatar(            radius: 22,            backgroundImage: _avatarProvider(avatar),            onBackgroundImageError: (_, __) {},          ),          const SizedBox(width: 8),          Expanded(            child: Column(              crossAxisAlignment: CrossAxisAlignment.start,              children: [                Text(                  name,                  style: const TextStyle(                    fontSize: 13,                    fontWeight: FontWeight.bold,                    fontFamily: 'Poppins',                  ),                  maxLines: 1,                  overflow: TextOverflow.ellipsis,                ),                const SizedBox(height: 2),                Row(                  children: [                    Icon(Icons.star_rounded, color: color, size: 16),                    const SizedBox(width: 3),                    Text(                      '$score pts',                      style: TextStyle(                        fontSize: 14,                        fontWeight: FontWeight.w800,                        color: color,                        fontFamily: 'Poppins',                      ),                    ),                  ],                ),              ],            ),          ),        ],      ),    );  }}// ============================================================================// BATTLE RESULT SCREEN// ============================================================================class BattleResultScreen extends StatelessWidget {  final String category;  final String difficulty;  final String gameCode;  final int myScore;  final int opponentScore;  final String myName;  final String opponentName;  final String myAvatar;  final String opponentAvatar;  final int totalQuestions;  final bool didIWin;  final Map<String, dynamic>? badgeAwarded; // ✅ NEW  const BattleResultScreen({    super.key,    required this.category,    required this.difficulty,    required this.gameCode,    required this.myScore,    required this.opponentScore,    required this.myName,    required this.opponentName,    required this.myAvatar,    required this.opponentAvatar,    required this.totalQuestions,    required this.didIWin,    this.badgeAwarded, // ✅ NEW  });  Color _getDifficultyColor() {    switch (difficulty.toUpperCase()) {      case "EASY":        return const Color(0xFF1D9358);      case "AVERAGE":        return const Color(0xFF046EB8);      case "DIFFICULT":        return const Color(0xFFBD442E);      default:        return const Color(0xFF1D9358);    }  }  @override  Widget build(BuildContext context) {    final color = _getDifficultyColor();    return Scaffold(      backgroundColor: Colors.white,      body: Center(        child: SingleChildScrollView(          child: Padding(            padding: const EdgeInsets.all(40),            child: Column(              mainAxisAlignment: MainAxisAlignment.center,              children: [                // Victory/Defeat                Text(                  didIWin ? 'VICTORY!' : 'DEFEAT',                  style: TextStyle(                    fontSize: 70,                    fontWeight: FontWeight.bold,                    color: didIWin ? const Color(0xFFC571E2) : Colors.grey,                    fontFamily: 'Poppins',                  ),                ),                const SizedBox(height: 20),                // ✅ Badge Progress Display (only for winner)                if (didIWin && badgeAwarded != null) ...[                  _buildBadgeProgress(color),                  const SizedBox(height: 20),                ],                const SizedBox(height: 20),                // Score display                Row(                  mainAxisAlignment: MainAxisAlignment.center,                  children: [                    _buildPlayerResult(myName, myAvatar, myScore),                    Padding(                      padding: const EdgeInsets.symmetric(horizontal: 40),                      child: Text(                        '$myScore : $opponentScore',                        style: const TextStyle(fontSize: 80, fontWeight: FontWeight.bold),                      ),                    ),                    _buildPlayerResult(opponentName, opponentAvatar, opponentScore),                  ],                ),                const SizedBox(height: 30),                Text('Questions: $totalQuestions of $totalQuestions', style: const TextStyle(fontSize: 16)),                const SizedBox(height: 40),                // Buttons                Row(                  mainAxisAlignment: MainAxisAlignment.center,                  children: [                    OutlinedButton(                      onPressed: () async {                        try {                          await AudioService().playClickSound();                        } catch (e) {                          debugPrint('Click sound not found: $e');                        }                        AudioService().playHomepageMusic(); // ✅ Restore homepage music                        Navigator.of(context).pop();                      },                      style: OutlinedButton.styleFrom(                        padding: const EdgeInsets.symmetric(horizontal: 30, vertical: 14),                        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(30)),                      ),                      child: const Text('EXIT', style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold)),                    ),                    const SizedBox(width: 20),                    ElevatedButton(                      onPressed: () async {                        try {                          await AudioService().playClickSound();                        } catch (e) {                          debugPrint('Click sound not found: $e');                        }                        AudioService().playHomepageMusic(); // ✅ Restore homepage music                        Navigator.of(context).pop();                      },                      style: ElevatedButton.styleFrom(                        backgroundColor: const Color(0xFF1D9358),                        padding: const EdgeInsets.symmetric(horizontal: 30, vertical: 14),                        shape: RoundedRectangleBorder(borderRadius: BorderRadius.circular(30)),                      ),                      child: const Text(                        'PLAY AGAIN',                        style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold, color: Colors.white),                      ),                    ),                  ],                ),              ],            ),          ),        ),      ),    );  }  // ✅ Badge progress widget  // ✅ Simple badge earned display - Shows for ANY win (1/3, 2/3, or 3/3)  Widget _buildBadgeProgress(Color color) {    final badgeUnlocked = badgeAwarded!['badge_unlocked'] ?? false;    final badgeNumber = badgeAwarded!['badge_number'];    final difficultyName = badgeAwarded!['difficulty'];    return Container(      padding: const EdgeInsets.all(24),      decoration: BoxDecoration(        gradient: LinearGradient(          colors: [color.withValues(alpha:0.2), color.withValues(alpha:0.05)],          begin: Alignment.topLeft,          end: Alignment.bottomRight,        ),        borderRadius: BorderRadius.circular(20),        border: Border.all(color: color, width: 3),      ),      child: Column(        children: [          Icon(            badgeUnlocked ? Icons.emoji_events : Icons.military_tech,            color: badgeUnlocked ? const Color(0xFFC571E2) : color,            size: 60,          ),          const SizedBox(height: 12),          Text(            badgeUnlocked ? 'BADGE #$badgeNumber UNLOCKED!' : 'BADGE EARNED!',            style: TextStyle(              fontSize: 24,              fontWeight: FontWeight.bold,              color: color,              fontFamily: 'Poppins',            ),          ),          const SizedBox(height: 8),          Container(            padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 8),            decoration: BoxDecoration(              color: color,              borderRadius: BorderRadius.circular(20),            ),            child: Text(              difficultyName.toUpperCase(),              style: const TextStyle(                fontSize: 14,                fontWeight: FontWeight.bold,                color: Colors.white,                fontFamily: 'Poppins',              ),            ),          ),          const SizedBox(height: 12),          Container(            padding: const EdgeInsets.all(12),            decoration: BoxDecoration(              color: Colors.white,              borderRadius: BorderRadius.circular(12),              border: Border.all(color: Colors.grey.shade300),            ),            child: Row(              mainAxisSize: MainAxisSize.min,              children: [                Icon(Icons.card_giftcard, color: color, size: 20),                const SizedBox(width: 8),                Flexible(                  child: Text(                    badgeUnlocked                        ? 'Visit Badges screen to claim!'                        : 'Keep winning to unlock badges!',                    style: const TextStyle(                      fontSize: 14,                      fontWeight: FontWeight.w600,                      color: Colors.black87,                    ),                    textAlign: TextAlign.center,                  ),                ),              ],            ),          ),        ],      ),    );  }  Widget _buildPlayerResult(String name, String avatar, int score) {    return Column(      children: [        CircleAvatar(          radius: 60,          backgroundImage: _avatarProvider(avatar),          onBackgroundImageError: (_, __) {},        ),        const SizedBox(height: 12),        Text(name, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),        const SizedBox(height: 8),        Row(          mainAxisSize: MainAxisSize.min,          children: [            const Icon(Icons.star, color: Color(0xFFC571E2), size: 24),            const SizedBox(width: 6),            Text('$score', style: const TextStyle(fontSize: 24, fontWeight: FontWeight.bold)),          ],        ),      ],    );  }}